CREATE   PROCEDURE [synapse_ce].[usp_Update_msevtmgt_attendeepass]
AS
BEGIN

	UPDATE tgt SET 
		tgt.[SinkCreatedOn] = src.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = src.[SinkModifiedOn],
		tgt.[statecode] = src.[statecode],
		tgt.[statuscode] = src.[statuscode],
		tgt.[createdby] = src.[createdby],
		tgt.[createdby_entitytype] = src.[createdby_entitytype],
		tgt.[createdonbehalfby] = src.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = src.[createdonbehalfby_entitytype],
		tgt.[modifiedby] = src.[modifiedby],
		tgt.[modifiedby_entitytype] = src.[modifiedby_entitytype],
		tgt.[modifiedonbehalfby] = src.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = src.[modifiedonbehalfby_entitytype],
		tgt.[msevtmgt_contact] = src.[msevtmgt_contact],
		tgt.[msevtmgt_contact_entitytype] = src.[msevtmgt_contact_entitytype],
		tgt.[msevtmgt_eventid] = src.[msevtmgt_eventid],
		tgt.[msevtmgt_eventid_entitytype] = src.[msevtmgt_eventid_entitytype],
		tgt.[msevtmgt_eventregistrationid] = src.[msevtmgt_eventregistrationid],
		tgt.[msevtmgt_eventregistrationid_entitytype] = src.[msevtmgt_eventregistrationid_entitytype],
		tgt.[msevtmgt_pass] = src.[msevtmgt_pass],
		tgt.[msevtmgt_pass_entitytype] = src.[msevtmgt_pass_entitytype],
		tgt.[msevtmgt_transactioncurrencyid] = src.[msevtmgt_transactioncurrencyid],
		tgt.[msevtmgt_transactioncurrencyid_entitytype] = src.[msevtmgt_transactioncurrencyid_entitytype],
		tgt.[owningbusinessunit] = src.[owningbusinessunit],
		tgt.[owningbusinessunit_entitytype] = src.[owningbusinessunit_entitytype],
		tgt.[owningteam] = src.[owningteam],
		tgt.[owningteam_entitytype] = src.[owningteam_entitytype],
		tgt.[owninguser] = src.[owninguser],
		tgt.[owninguser_entitytype] = src.[owninguser_entitytype],
		tgt.[transactioncurrencyid] = src.[transactioncurrencyid],
		tgt.[transactioncurrencyid_entitytype] = src.[transactioncurrencyid_entitytype],
		tgt.[ownerid] = src.[ownerid],
		tgt.[ownerid_entitytype] = src.[ownerid_entitytype],
		tgt.[msevtmgt_passprice] = src.[msevtmgt_passprice],
		tgt.[msevtmgt_passprice_base] = src.[msevtmgt_passprice_base],
		tgt.[createdbyname] = src.[createdbyname],
		tgt.[createdbyyominame] = src.[createdbyyominame],
		tgt.[createdon] = src.[createdon],
		tgt.[createdonbehalfbyname] = src.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = src.[createdonbehalfbyyominame],
		tgt.[exchangerate] = src.[exchangerate],
		tgt.[importsequencenumber] = src.[importsequencenumber],
		tgt.[modifiedbyname] = src.[modifiedbyname],
		tgt.[modifiedbyyominame] = src.[modifiedbyyominame],
		tgt.[modifiedon] = src.[modifiedon],
		tgt.[modifiedonbehalfbyname] = src.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = src.[modifiedonbehalfbyyominame],
		tgt.[msevtmgt_attendeepassid] = src.[msevtmgt_attendeepassid],
		tgt.[msevtmgt_contactname] = src.[msevtmgt_contactname],
		tgt.[msevtmgt_contactyominame] = src.[msevtmgt_contactyominame],
		tgt.[msevtmgt_eventidname] = src.[msevtmgt_eventidname],
		tgt.[msevtmgt_eventregistrationidname] = src.[msevtmgt_eventregistrationidname],
		tgt.[msevtmgt_name] = src.[msevtmgt_name],
		tgt.[msevtmgt_passname] = src.[msevtmgt_passname],
		tgt.[msevtmgt_transactioncurrencyidname] = src.[msevtmgt_transactioncurrencyidname],
		tgt.[overriddencreatedon] = src.[overriddencreatedon],
		tgt.[owneridname] = src.[owneridname],
		tgt.[owneridyominame] = src.[owneridyominame],
		tgt.[owningbusinessunitname] = src.[owningbusinessunitname],
		tgt.[timezoneruleversionnumber] = src.[timezoneruleversionnumber],
		tgt.[transactioncurrencyidname] = src.[transactioncurrencyidname],
		tgt.[utcconversiontimezonecode] = src.[utcconversiontimezonecode],
		tgt.[versionnumber] = src.[versionnumber]

	FROM [synapse_ce].[msevtmgt_attendeepass] tgt
		INNER JOIN [staging_ce].[msevtmgt_attendeepass] src
			ON tgt.[Id] = src.[Id]

END
